contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept parameters: amount to deposit in Put (putAmt), unlock time to set, and amount to attempt to Collect (collectAmt).
    // The function is payable so it can send Ether to c; require ensures this contract has enough balance to send putAmt.
    function run(uint putAmt, uint unlockTime, uint collectAmt) public payable {
        require(address(this).balance >= putAmt, "not enough balance to Put");
        // Read balances before any calls
        uint beforeAccBal = c.Acc(address(this)).balance;
        uint beforeCbal = address(c).balance;

        // Do Put: send putAmt to c which should increase both c's ether balance and recorded Acc[msg.sender].balance
        c.Put{value: putAmt}(unlockTime);

        // Read after-put recorded balance and contract balance
        uint afterPutAccBal = c.Acc(address(this)).balance;
        uint afterPutCbal = address(c).balance;

        // Attempt Collect for collectAmt and record whether it reverted
        bool reverted;
        try c.Collect{value:0}(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-collect recorded balance and contract balance
        uint afterCollectAccBal = c.Acc(address(this)).balance;
        uint afterCollectCbal = address(c).balance;

        // General rule asserted:
        // If Collect did not revert then:
        // 1) The recorded balance decreased by exactly collectAmt compared to afterPutAccBal (no underflow because Collect would have required sufficient balance).
        // 2) The contract's ether balance decreased by exactly collectAmt as well.
        // Also ensure that if Collect did revert then recorded and contract balances did not change because the call reverted.
        assert(
            (!reverted && afterPutAccBal >= collectAmt &&
                afterCollectAccBal + collectAmt == afterPutAccBal &&
                afterPutCbal >= collectAmt &&
                afterCollectCbal + collectAmt == afterPutCbal)
            ||
            (reverted && afterCollectAccBal == afterPutAccBal && afterCollectCbal == afterPutCbal)
        );
    }

    // receive allows this test contract to accept refunds/transfers during Collect
    receive() external payable {}
}

contract InvMutTest {
