        // Assert the general invariant:
        // If Collect did not revert then midAccBal >= collectAmt and both the recorded balance and c's ether balance
        // decreased by exactly collectAmt. If Collect reverted then balances remain unchanged from mid values.
        assert(
            (!reverted && midAccBal >= collectAmt && afterAccBal + collectAmt == midAccBal && midCbal >= collectAmt && afterCbal + collectAmt == midCbal)
            ||
