        c.Put{value: putAmt}(unlockTime);

        // Read Acc and c balance after Put and before Collect
        (uint midUnlock, uint midAccBal) = c.Acc(address(this));
        uint midCbal = address(c).balance;

        // Attempt Collect and record whether it reverted
        bool reverted;
        try c.Collect{value:0}(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read Acc and c balance after Collect
        (uint afterUnlock, uint afterAccBal) = c.Acc(address(this));
        uint afterCbal = address(c).balance;

        // General rule to hold for all inputs:
        // If Collect succeeded then the recorded balance decreased exactly by collectAmt
        // (i.e. afterAccBal + collectAmt == midAccBal), and c's ether balance did not increase
        // (afterCbal <= midCbal) and decreased by at least the collected amount
        // (midCbal >= afterCbal && midCbal - afterCbal >= collectAmt).
        // If Collect reverted then recorded balance and c balance remain unchanged from mid values.
        assert(
            (!reverted && afterAccBal + collectAmt == midAccBal && midCbal >= afterCbal && (midCbal - afterCbal) >= collectAmt)
            ||
            (reverted && afterAccBal == midAccBal && afterCbal == midCbal)
        );
    }

