    function run(uint deposit, uint putUnlock, uint collectAmt) public payable {
        // ensure test contract can send the deposit
        require(address(this).balance >= deposit);

        // observe before-values
        (uint beforeUnlock, uint beforeAccBal) = c.Acc(address(this));
        uint beforeCbal = address(c).balance;

        // perform a Put to set up funds (may revert)
        bool putReverted;
        try c.Put{value: deposit}(putUnlock) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // observe after Put (before Collect)
        (uint midUnlock, uint midAccBal) = c.Acc(address(this));
        uint midCbal = address(c).balance;

        // Now attempt Collect of collectAmt (may revert). Collect is payable in source but we won't send value.
        bool collectReverted;
        try c.Collect{value: 0}(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // observe after Collect
        (uint afterUnlock, uint afterAccBal) = c.Acc(address(this));
        uint afterCbal = address(c).balance;

        // General rule:
