        // - If Collect reverted then neither the stored Acc balance nor C's on-chain balance increased compared to just before Collect.
        // This avoids assuming exact equality because Collect only allows withdrawal when acc.balance>=MinSum and acc.balance>=_am and time>unlock.

        assert(
            // Case: Collect reverted => balances did not increase compared to mid-state
            (collectReverted && afterAccBal <= midAccBal && afterCbal <= midCbal)
            ||
            // Case: Collect succeeded => neither balance increased, and both decreased by at least collectAmt or to zero
            (!collectReverted
                && afterAccBal <= midAccBal
                && afterCbal <= midCbal
                && (midAccBal >= collectAmt ? (midAccBal - afterAccBal) >= collectAmt : afterAccBal <= midAccBal)
                && (midCbal >= collectAmt ? (midCbal - afterCbal) >= collectAmt : afterCbal <= midCbal)
            )
        );
    }

    // receive so contract can accept Ether from C during Collect
    receive() external payable {}
}

