    // and address(c).balance decreased by collected_amount. If Collect reverted or didn't send, balances unchanged
    // relative to expectation.

    function run(uint putUnlock, uint putAmount, uint collectAmount) public payable {
        require(address(this).balance >= putAmount, "not enough balance to fund Put");
        // record contract balance before any operations
        uint cBalBefore = address(c).balance;

        // Ensure putAmount is at least 0 (it is uint). Make a Put call with value putAmount.
        c.Put{value: putAmount}(putUnlock);

        // read holder balance after Put
        (uint unlockAfterPut, uint balAfterPut) = c.Acc(address(this));

        // Now attempt Collect. We capture whether it reverted.
        bool collectReverted = false;
        try c.Collect{value: 0}(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // read holder balance and contract balance after Collect attempt
        (uint unlockAfterCollect, uint balAfterCollect) = c.Acc(address(this));
        uint cBalAfter = address(c).balance;

