        try c.Collect{value: 0}(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe final state
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterCbal = address(c).balance;
        uint afterThis = address(this).balance;

        // Assert the general invariant:
        // 1) Put increased c's external balance by exactly putAmt
        // 2) Put increased the recorded balance by at least putAmt (no loss in accounting)
        // 3) Collect never increases the recorded balance (afterBal <= midBal)
        // 4) If Collect succeeded then c's balance decreased by the amount that this contract's balance increased, and recorded balance decreased by at least that amount.
        assert(
            // 1
            midCbal == beforeCbal + putAmt
            // 2
            && midBal >= beforeBal + putAmt
            // 3
            && afterBal <= midBal
            // 4
            && (
                reverted
                || (
                    !reverted
                    && afterThis == midThis + (midCbal - afterCbal) // this contract gained exactly the ETH lost by c
                    && midBal >= afterBal + (midCbal - afterCbal)   // recorded balance decreased by at least that withdrawn amount
                )
            )
        );
    }

    // allow receiving ETH from c on Collect
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Params:
    // putAmt: Ether to send with Put
    // unlockTime: argument to Put (may be in future to allow Collect to fail/succeed)
    // collectAmt: amount to attempt to Collect
    function run(uint putAmt, uint unlockTime, uint collectAmt) public payable {
        // ensure we have funds to send for Put
        require(address(this).balance >= putAmt);

        // read recorded balance before any action
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));

        // perform Put sending putAmt
        c.Put{value: putAmt}(unlockTime);

        // read recorded balance after Put
        (uint midUnlock, uint midBal) = c.Acc(address(this));

        // attempt Collect and record revert status
        bool reverted;
        try c.Collect{value: 0}(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read recorded balance after Collect attempt
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));

        // If Collect succeeded then the recorded balance must not have increased,
        // and must have decreased by at most the attempted collectAmt (i.e., midBal >= afterBal and midBal - afterBal <= collectAmt <= midBal).
        // We express a conservative general rule: on successful Collect, afterBal <= midBal and (midBal - afterBal) <= collectAmt || collectAmt > midBal (the latter allows that Collect may have been constrained by balance).
        // Combine into a single assert over observable values and revert flag.
        assert(
            reverted || (
                // Collect succeeded
                afterBal <= midBal
                && (midBal - afterBal) <= collectAmt
            )
        );
    }

    receive() external payable { }
}

